"""Profiling: BLITZLLVM_PROFILE_FPS=1 and the command ProfileFPS only report in a program that was compiled with --profile (or -d).

  profile.py BLITZCC PROGRAM.bb WORKDIR on|debug|off [env|command|silenced|results]

env (the default): the environment variable asks for the report. command: the program asks with ProfileFPS 1 and the
environment is clean. silenced: the environment asks, but the program turns the timers off with ProfileEnable 0.
results: the program takes the text, the file and the numbers of every frame itself and prints what it got, which is something with
--profile and nothing without. Without --profile the commands are no-ops, so the program still has to compile and run.
"""
import os
import subprocess
import sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "../../tools"))
import procutil  # noqa: E402


def main():
    blitzcc, source, work, mode = sys.argv[1], sys.argv[2], os.path.abspath(sys.argv[3]), sys.argv[4]
    variant = sys.argv[5] if len(sys.argv) > 5 else "env"
    os.makedirs(work, exist_ok=True)
    exe = os.path.join(work, "profile")
    flags = {"on": ["--profile"], "debug": ["-d"], "off": []}[mode]
    procutil.run([blitzcc] + flags + [source, "-o", exe], check=True, stdout=subprocess.DEVNULL)
    env = {k: v for k, v in os.environ.items() if not k.startswith("BLITZLLVM_PROFILE_")}
    if variant != "command":
        env["BLITZLLVM_PROFILE_FPS"] = "1"
    if variant == "results":
        result = procutil.run([exe], env=env, cwd=work, capture_output=True, text=True, timeout=60)
        line = [l for l in result.stderr.splitlines() if l.startswith("frames=")]
        if result.returncode != 0 or not line:
            print("profile (results): the program failed with %d.\n%s\n%s" % (result.returncode, result.stdout, result.stderr))
            return 1
        got = dict(item.split("=") for item in line[0].split())
        if mode == "off":
            expected_values = {"frames": "0", "frame0": "0", "text": "0", "file": "0", "number": "0"}
        else:
            expected_values = {}
            if int(got["frames"]) < 10 or got["frame0"] != "1" or got["number"] != "1" or int(got["text"]) < 100 or int(got["file"]) < 100:
                print("profile (results): got %s, but frames, text and file should all have something." % line[0])
                return 1
        for key, value in expected_values.items():
            if got[key] != value:
                print("profile (results): got %s, but %s should be %s without --profile." % (line[0], key, value))
                return 1
        if got["items"] != "1":
            print("profile (results): not every item has a name: %s" % line[0])
            return 1
        return 0
    result = procutil.run([exe], env=env, capture_output=True, text=True, timeout=60)
    reported = "fps:" in result.stderr
    expected = (mode != "off") and variant != "silenced"
    if result.returncode != 0:
        print("profile: the program failed with %d.\n%s" % (result.returncode, result.stderr))
        return 1
    if reported != expected:
        print("profile (%s): the report %s, but the program was compiled with profiling %s.\n%s" % (variant, "came" if reported else "did not come", mode, result.stderr))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
